create extension if not exists pgcrypto;
create type user_role as enum ('buyer','seller','admin');
create type product_status as enum ('draft','moderation','published','rejected','archived');
create type order_status as enum ('created','paid','seller_confirmed','ready_for_handover','completed','cancelled','refunded','disputed');
create type fulfillment_type as enum ('meeting','pickup');
create type ledger_type as enum ('sale','commission','refund','payout','adjustment');
create table if not exists users(id uuid primary key default gen_random_uuid(),telegram_id bigint not null unique,first_name text not null,last_name text,username text,language_code text,is_premium boolean not null default false,role user_role not null default 'buyer',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists seller_profiles(user_id uuid primary key references users(id) on delete cascade,display_name text not null,description text,rating numeric(3,2) not null default 0 check(rating between 0 and 5),completed_sales integer not null default 0,reliability_score numeric(5,2) not null default 100 check(reliability_score between 0 and 100),created_at timestamptz not null default now());
create table if not exists stores(id uuid primary key default gen_random_uuid(),seller_id uuid not null unique references users(id) on delete cascade,name text not null,description text,logo_url text,created_at timestamptz not null default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),parent_id uuid references categories(id) on delete set null,name text not null,slug text not null unique,restricted boolean not null default false,age_restriction integer,created_at timestamptz not null default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),seller_id uuid not null references users(id),store_id uuid references stores(id),category_id uuid references categories(id),title text not null,slug text not null unique,description text,price_minor bigint not null check(price_minor>0),currency char(3) not null default 'RUB',status product_status not null default 'draft',fulfillment_type fulfillment_type not null default 'pickup',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists inventory(product_id uuid primary key references products(id) on delete cascade,stock integer not null default 0 check(stock>=0),reserved integer not null default 0 check(reserved>=0 and reserved<=stock),updated_at timestamptz not null default now());
create table if not exists product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,url text not null,sort_order integer not null default 0);
create table if not exists carts(id uuid primary key default gen_random_uuid(),buyer_id uuid not null unique references users(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists cart_items(cart_id uuid not null references carts(id) on delete cascade,product_id uuid not null references products(id) on delete cascade,quantity integer not null check(quantity>0),created_at timestamptz not null default now(),primary key(cart_id,product_id));
create table if not exists orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references users(id),status order_status not null default 'created',total_minor bigint not null check(total_minor>=0),currency char(3) not null default 'RUB',platform_fee_minor bigint not null default 0 check(platform_fee_minor>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists seller_orders(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,seller_id uuid not null references users(id),status order_status not null default 'created',subtotal_minor bigint not null check(subtotal_minor>=0),platform_fee_minor bigint not null default 0 check(platform_fee_minor>=0),seller_amount_minor bigint not null default 0 check(seller_amount_minor>=0),fulfillment_type fulfillment_type not null,created_at timestamptz not null default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),seller_order_id uuid not null references seller_orders(id) on delete cascade,product_id uuid not null references products(id),title_snapshot text not null,unit_price_minor bigint not null check(unit_price_minor>0),quantity integer not null check(quantity>0),total_minor bigint not null check(total_minor>0),created_at timestamptz not null default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references orders(id) on delete cascade,provider text not null,provider_payment_id text,status text not null default 'pending',amount_minor bigint not null check(amount_minor>=0),currency char(3) not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists payment_transactions(id uuid primary key default gen_random_uuid(),payment_id uuid not null references payments(id) on delete cascade,idempotency_key text not null unique,provider_event_id text unique,event_type text not null,payload jsonb not null,created_at timestamptz not null default now());
create table if not exists ledger_entries(id uuid primary key default gen_random_uuid(),seller_id uuid not null references users(id),order_id uuid references orders(id),type ledger_type not null,amount_minor bigint not null,currency char(3) not null,description text,created_at timestamptz not null default now());
create table if not exists payouts(id uuid primary key default gen_random_uuid(),seller_id uuid not null references users(id),amount_minor bigint not null check(amount_minor>0),currency char(3) not null,status text not null default 'pending',provider_payout_id text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists favorites(user_id uuid not null references users(id) on delete cascade,product_id uuid not null references products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table if not exists reviews(id uuid primary key default gen_random_uuid(),order_item_id uuid not null references order_items(id),buyer_id uuid not null references users(id),product_id uuid not null references products(id),rating integer not null check(rating between 1 and 5),text text,created_at timestamptz not null default now(),unique(order_item_id,buyer_id));
create table if not exists disputes(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),buyer_id uuid not null references users(id),reason text not null,description text,status text not null default 'open',created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,type text not null,title text not null,body text,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists moderation_queue(id uuid primary key default gen_random_uuid(),product_id uuid not null unique references products(id) on delete cascade,status text not null default 'pending',reason text,reviewed_by uuid references users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists chat_threads(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references users(id),seller_id uuid not null references users(id),product_id uuid references products(id),created_at timestamptz not null default now(),unique(buyer_id,seller_id,product_id));
create table if not exists chat_messages(id uuid primary key default gen_random_uuid(),thread_id uuid not null references chat_threads(id) on delete cascade,sender_id uuid not null references users(id),body text not null check(length(body) between 1 and 4000),created_at timestamptz not null default now());
create table if not exists offers(id uuid primary key default gen_random_uuid(),thread_id uuid not null references chat_threads(id) on delete cascade,seller_id uuid not null references users(id),buyer_id uuid not null references users(id),product_id uuid references products(id),title text not null,price_minor bigint not null check(price_minor>0),currency char(3) not null,quantity integer not null default 1 check(quantity>0),fulfillment_type fulfillment_type not null,status text not null default 'pending',expires_at timestamptz,created_at timestamptz not null default now());
create index if not exists idx_products_category_status on products(category_id,status);
create index if not exists idx_products_seller_status on products(seller_id,status);
create index if not exists idx_orders_buyer_created on orders(buyer_id,created_at desc);
create index if not exists idx_seller_orders_seller_created on seller_orders(seller_id,created_at desc);
create index if not exists idx_ledger_seller_created on ledger_entries(seller_id,created_at desc);
create index if not exists idx_notifications_user_created on notifications(user_id,created_at desc);
create index if not exists idx_chat_messages_thread_created on chat_messages(thread_id,created_at);